export function install(t){Object.assign(t,{init:async function(){t.captureUi(),t.loadSettings(),t.state.timer||(t.state.timer=window.setInterval(()=>t.tick(),t.TICK_MS));if(t.state.catalog)return void t.render(t.state.position||t.positionAt(Date.now()));try{const a=await fetch(t.CATALOG_URL,{cache:"force-cache",credentials:"same-origin"});if(!a.ok)throw new Error(String(a.status));t.state.catalog=await a.json()}catch{return t.state.catalog=null,void t.render(null)}t.buildPool(),t.tick();let a=!1;try{a="1"===localStorage.getItem(t.STORAGE_ACTIVE)}catch{}a&&t.start()}})}